layers.vertex:
attribute vec3 aVertexPosition;
attribute vec2 aTextureCoord;
uniform mat4 uModelMatrix;
uniform mat4 uViewMatrix;
uniform mat4 uProjectionMatrix;
varying float vDepth;
varying float vHeight;
varying vec2 vTextureCoord;
varying vec2 vWorld;
varying vec2 vSurface;
varying vec3 vWorldPos;

void main(void) {
  vec4 world = uModelMatrix * vec4(aVertexPosition, 1.0);
  vec4 v = uViewMatrix * world;
  vDepth = -v.z;
  vHeight = world.y;
  vTextureCoord = aTextureCoord;
  vWorld = world.xz;
  vSurface = vec2(aVertexPosition.x + aVertexPosition.z, aVertexPosition.y) + uModelMatrix[3].xz * 0.37;
  vWorldPos = world.xyz;
  vec4 clip = uProjectionMatrix * v;
  clip.z -= 0.00001 * clip.w;
  gl_Position = clip;
}

layers.fragment:
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform sampler2D uSampler;
uniform vec3 uMaterialDiffuse;
uniform int uHasFog;
uniform vec3 uFogColor;
uniform float uFogNear;
uniform float uFogFar;
varying float vDepth;
varying float vHeight;
varying vec2 vTextureCoord;
varying vec2 vWorld;
varying vec2 vSurface;
varying vec3 vWorldPos;


const vec3 STEEL = vec3(0.0824, 0.1059, 0.1529);
const vec3 RUST_DARK = vec3(0.1490, 0.0824, 0.0510);
const vec3 RUST = vec3(0.2824, 0.1490, 0.0745);
const vec3 RUST_BRIGHT = vec3(0.4392, 0.2275, 0.0941);

float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}


uniform int uNbLights;
uniform vec3 uAmbientLight;
uniform vec3 uLightPosition[8];
uniform vec3 uLightDiffuse[8];
uniform vec3 uLightAttenuation[8];

vec3 surfaceLight(vec3 worldPos, float emissive) {
  if (uNbLights <= 0)
    return vec3(1.0);
  vec3 total = uAmbientLight;
  for (int i = 0; i < 8; i++) {
    if (i >= uNbLights)
      break;
    vec3 diff = uLightDiffuse[i];
    if (diff.x + diff.y + diff.z <= 0.001)
      continue;
    vec3 delta = uLightPosition[i] - worldPos;
    if (delta.x * delta.x + delta.z * delta.z > 160000.0)
      continue;
    float isCeilingFixture = step(54.0, uLightPosition[i].y);
    float onCeiling = step(58.0, worldPos.y) * isCeilingFixture;
    float verticalSpan = mix(delta.y, 62.0, onCeiling);
    vec3 lightVec = vec3(delta.x, verticalSpan, delta.z);
    float distSq = dot(lightVec, lightVec);
    if (distSq > 160000.0)
      continue;
    vec3 att = uLightAttenuation[i];
    if (att.z > 0.001 && distSq >= 18225.0)
      continue;
    float dist = sqrt(distSq);
    float shortRange = step(0.001, att.z);
    float rangeCutoff = mix(1.0, 1.0 - smoothstep(75.0, 135.0, dist), shortRange);
    float attenuation = rangeCutoff / max(att.x + att.y * dist + att.z * distSq, 0.0001);
    float downward = clamp((uLightPosition[i].y - worldPos.y) / max(dist, 1.0), 0.0, 1.0);
    float spread = mix(1.05, 0.5 + 0.75 * downward * downward, isCeilingFixture);
    total += diff * (attenuation * spread);
  }
  return mix(min(total, vec3(2.5)), max(total, vec3(1.35)), clamp(emissive, 0.0, 1.0));
}


vec3 sampleDirtCell(vec2 p, float seed) {
  vec2 tileId = floor(p / 64.0);
  float cell = floor(hash(tileId + seed) * 8.0);
  vec2 t = floor(mod(p, 64.0) * 4.0) + 0.5;
  return texture2D(uSampler, vec2((cell * 256.0 + t.x) / 2048.0, t.y / 256.0)).rgb;
}

vec3 sampleRockCell(vec2 p, float seed) {
  vec2 tileId = floor(p / 64.0);
  float idx = floor(hash(tileId + seed) * 7.0);
  float cell = idx >= 5.0 ? idx + 1.0 : idx;
  vec2 t = floor(mod(p, 64.0) * 4.0) + 0.5;
  return texture2D(uSampler, vec2((cell * 256.0 + t.x) / 2048.0, t.y / 256.0)).rgb;
}

void main(void) {
  if (vHeight < -0.21)
    discard;
  if (uHasFog == 1 && vDepth >= uFogFar) {
    gl_FragColor = vec4(uFogColor, 0.5);
    return;
  }
  float isFloor = step(vHeight, -0.15);
  vec4 uvSample = texture2D(uSampler, vTextureCoord);
  if (uvSample.a < 0.5)
    discard;
  vec3 uvTex = uvSample.rgb;
  float lit = (1.0 - isFloor) * smoothstep(0.08, 0.22, uvTex.g - uvTex.r);
  vec3 color = uvTex;
  float ember = 0.0;

  if (lit < 0.92) {
    vec2 surf = mix(vSurface, vWorld, isFloor);
    vec2 warp = vec2(
      noise(surf / 54.0 + vec2(3.7, 9.2)) - 0.5,
      noise(surf / 48.0 + vec2(19.4, 7.1)) - 0.5
    ) * 22.0;
    vec2 pA = surf + warp;
    vec3 dirt = isFloor > 0.5 ? sampleDirtCell(pA, 0.0) : sampleRockCell(pA, 0.0);
    if (vDepth < 680.0) {
      vec2 pB = vec2(surf.x * 0.58 - surf.y * 0.51, surf.x * 0.51 + surf.y * 0.58) + warp * 0.7 + vec2(31.4, 73.8);
      vec3 dirtB = isFloor > 0.5 ? sampleDirtCell(pB, 17.3) : sampleRockCell(pB, 17.3);
      float blendAB = smoothstep(0.24, 0.76, noise(surf / 72.0 + 5.0));
      dirt = mix(dirt, dirtB, blendAB);
    }
    float near = 1.0 - smoothstep(180.0, 520.0, vDepth);
    float grit = 0.0;
    if (near > 0.01) {
      vec2 pC = vec2(-surf.x * 0.43 - surf.y * 0.67, surf.x * 0.67 - surf.y * 0.43) - warp * 0.5 + vec2(89.1, 17.6);
      vec3 dirtC = isFloor > 0.5 ? sampleDirtCell(pC, 43.9) : sampleRockCell(pC, 43.9);
      float blendC = smoothstep(0.32, 0.78, noise(surf / 112.0 + 29.0));
      dirt = mix(dirt, dirtC, blendC * 0.58);
      vec2 texel = floor(surf * 4.0) * 0.25;
      grit = ((noise(texel / 3.9) - 0.5) * 0.6 + (noise(texel / 1.8 + 17.0) - 0.5) * 0.4) * 0.14 * near;
    }
    dirt = mix(vec3(0.50, 0.21, 0.10), dirt, 0.35 + 0.65 * near);

    float macro = noise(surf / 190.0 + 19.0) * 0.55 + noise(pA / 74.0 + 7.0) * 0.45;
    float ridge = 0.5;
    float scree = 0.5;
    if (vDepth < 680.0) {
      ridge = 1.0 - abs(noise((pA + warp * 0.8) / 36.0 + 41.0) * 2.0 - 1.0);
      scree = noise((surf - warp) / 21.0 + 63.0);
    }
    vec3 ochre = vec3(0.78, 0.39, 0.17);
    vec3 rustClay = vec3(0.62, 0.24, 0.11);
    vec3 basalt = vec3(0.22, 0.11, 0.07);
    vec3 rockCol = dirt;
    rockCol = mix(rockCol, ochre, smoothstep(0.54, 0.84, macro * 0.6 + ridge * 0.4) * 0.32);
    rockCol = mix(rockCol, rustClay, smoothstep(0.55, 0.82, scree * 0.65 + (1.0 - ridge) * 0.35) * 0.24);
    rockCol = mix(rockCol, basalt, smoothstep(0.58, 0.85, (1.0 - macro) * 0.65 + (1.0 - scree) * 0.35) * 0.36);
    rockCol = clamp(rockCol + grit, 0.0, 1.0);
    color = mix(rockCol, uvTex, lit);
    ember = isFloor * smoothstep(0.32, 0.58, dirt.r - dirt.g * 0.65) * smoothstep(0.45, 0.75, dirt.g);
  }
  color *= uMaterialDiffuse * surfaceLight(vWorldPos, max(lit, ember * 0.45));
  if (uHasFog == 1) {
    float fade = clamp((vDepth - uFogNear) / (uFogFar - uFogNear), 0.0, 1.0);
    color = mix(color, uFogColor, fade);
  }
  gl_FragColor = vec4(color, 0.5);
}

